const HandleChange = (e) => {
  const value = e.target.value.toLowerCase();

  if (value === "") {
    setList(Posts);
    setQuery(value);
    return;
  }

  const results = Posts.filter((post) =>
    post.title.toLowerCase().includes(value)
  );

  setQuery(value);
  setList(results);
};
``
